mapper.delete:
delete from hls_doc_layout_screen
where
    layout_code = #{layout_code}
   and tab_code = #{tab_code}

mapper.select:
select count(1)
from (
    select count(s.column_name)
    from hls_doc_layout_screen s
    where s.column_name is not null
    and s.layout_code = #{layout_code}
    and s.tab_code = #{tab_code}
    group by s.column_name
    having count(1) > 1
) tmp

select nvl(t.column_count, 0)
from hls_doc_layout_tab t
where t.layout_code = #{layout_code}
and t.tab_code = #{tab_code}
